704	        &mut self,
705	        guard: usize,
706	        if_true: &'a Body,
707	        if_false: &'a Decision,
708	    ) -> CaseBody<'a> {
709	        let DecisionKind::Case { clauses } = &self.kind else {
710	            unreachable!("Guards cannot appear in let assert decision trees")
711	        };
712	
